const SPRITES: Record<string, Run[]> = {
  "design": DESIGN,
  "art-direction": ART_DIRECTION,
  "vibe-coding": VIBE_CODING,
  "motion": MOTION,
  "world-building": WORLD_BUILDING,
  "system-thinking": SYSTEM_THINKING,
};

function usePixelCanvas(name: string, active: boolean) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    canvas.width  = TW * PS;
    canvas.height = TH * PS;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!active) return;
    const runs = SPRITES[name];
    if (!runs) return;
    for (const [x, y, run, r, g, b] of runs) {
      ctx.fillStyle = `rgb(${r},${g},${b})`;
      ctx.fillRect(x * PS, y * PS, run * PS, PS);
    }
  }, [name, active]);

  return ref;
}

export function PixelAvatar({
  name,
  size = 1,
  className,
  style,
}: {
  name: string;
  size?: number;
  className?: string;
  style?: React.CSSProperties;
}) {
  const [drawn, setDrawn] = useState(false);
  const ref = usePixelCanvas(name, drawn);

  useEffect(() => { setDrawn(true); }, []);

  const px = TW * PS * size;
  const py = TH * PS * size;

  return (
    <canvas
      ref={ref}
      width={400}
      height={400}
      className={className}
      style={{ imageRendering: "pixelated", display: "block", width: `${px}px`, height: `${py}px`, ...style }}
    />
  );
}

/**
 * HoverWord, wrap any text, shows pixel avatar on hover
 *
 * Usage:
 *   <HoverWord name="design">DESIGN</HoverWord>
 *   <HoverWord name="art-direction">ART DIRECTION</HoverWord>
 *   <HoverWord name="vibe-coding">VIBE CODING</HoverWord>
 *   <HoverWord name="motion">MOTION</HoverWord>
 *   <HoverWord name="world-building">WORLD BUILDING</HoverWord>
 *   <HoverWord name="system-thinking">SYSTEM THINKING</HoverWord>
 */
export function HoverWord({
  name,
  children,
  avatarSize = 0.6,
  className,
}: {
  name: string;
  children: React.ReactNode;
  avatarSize?: number;
  className?: string;
}) {
  const [hovered, setHovered] = useState(false);
  const [pos, setPos] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e: React.MouseEvent) => {
    setPos({ x: e.clientX, y: e.clientY });
  };

  return (
    <span
      className={`relative inline-block cursor-pointer ${className ?? ""}`}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onMouseMove={handleMouseMove}
    >
      {children}

      {hovered && (
        <span
          className="pointer-events-none fixed z-[999]"
          style={{
            left: pos.x + 16,
            top:  pos.y - 20,
            transform: "translateY(-100%)",
          }}
        >
          <PixelAvatar name={name} size={avatarSize} />
        </span>
      )}
    </span>
  );
}